def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast cooperative start
    if n < 8:
        last_o = history[-1][1]
        if last_o == 'D':
            return 'D'
        return 'C'

    opp_defects = 0
    my_defects = 0
    opp_coops = 0
    for m, o in history:
        if o == 'D':
            opp_defects += 1
        else:
            opp_coops += 1
        if m == 'D':
            my_defects += 1

    last_m, last_o = history[-1]

    # Track opponent defection streak
    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    # Track our cooperation streak
    my_streak_c = 0
    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_streak_c += 1
        else:
            break
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    # Near end: exploit confirmed cooperators
    if n >= 92:
        if opp_defects <= 2:
            return 'D' if n >= 96 else 'C'
        if opp_defects * 4 < n:
            return 'D'
        if last_o == 'D':
            return 'D'
        return 'C'

    # Highly cooperative opponent: keep cooperating, rare test
    if opp_defects == 0:
        if n >= 20 and n % 30 == 0:
            return 'D'
        return 'C'

    if opp_defects * 10 <= n:
        if n >= 15 and n % 23 == 0:
            return 'D'
        return 'C'

    # Heavy defector: mostly defect, occasionally probe
    if opp_defects * 2 >= n:
        # If mutual defection loop, break out occasionally
        if last_m == 'D' and last_o == 'D' and opp_streak >= 3:
            return 'C' if rng.random() < 0.35 else 'D'
        if last_o == 'D':
            return 'D'
        # Opponent cooperated, reward it
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    # Moderate opponent: tit-for-tat with conditional forgiveness
    if last_o == 'D':
        # Forgive if our last move was C and opponent's overall rate is decent
        if last_m == 'C' and opp_defects * 5 < n:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Break long DD loops when opponent is not too bad
        if last_m == 'D' and opp_streak >= 2 and opp_defects * 3 < n:
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D'

    # last_o == 'C'
    # If we've been defecting while they cooperated, return to cooperation
    if my_streak_d >= 1:
        return 'C'
    # Rare probe against non-defectors in mid-late game
    if n > 40 and opp_defects > 0 and n % 19 == 0:
        return 'D'
    return 'C'
